import { Page } from '@playwright/test';

export interface FakeMicrophoneOptions {
  /** Tone frequency in Hz. */
  readonly frequency?: number;
  readonly amplitude?: number;
  /** Key-down spans in seconds; the pattern loops after `loopSeconds`. Omit for a steady tone. */
  readonly spans?: readonly (readonly [number, number])[];
  readonly loopSeconds?: number;
  /** Reject getUserMedia with this DOMException name (e.g. NotAllowedError). */
  readonly failWith?: string;
}

/**
 * Replaces getUserMedia with a real MediaStream generated by Web Audio (oscillator → gain →
 * MediaStreamDestination). The app's full capture pipeline (MediaStreamSource → AudioWorklet)
 * runs unchanged, without touching OS microphone permissions – which headless browsers on
 * macOS cannot grant.
 */
export async function installFakeMicrophone(
  page: Page,
  options: FakeMicrophoneOptions = {},
): Promise<void> {
  await page.addInitScript((opts: FakeMicrophoneOptions) => {
    const w = window as unknown as { __fakeMic: { calls: number; stopped: number } };
    w.__fakeMic = { calls: 0, stopped: 0 };
    const devices = [
      { kind: 'audioinput', deviceId: 'default', groupId: 'g', label: 'Default - Fake Mic' },
      { kind: 'audioinput', deviceId: 'fake-usb', groupId: 'g', label: 'Fake USB Mic' },
    ];
    const md = navigator.mediaDevices;
    md.enumerateDevices = async () =>
      devices.map((d) => ({ ...d, toJSON: () => d })) as unknown as MediaDeviceInfo[];
    md.getUserMedia = async () => {
      w.__fakeMic.calls++;
      if (opts.failWith) throw new DOMException('fake failure', opts.failWith);
      const ctx = new AudioContext();
      await ctx.resume();
      const osc = ctx.createOscillator();
      osc.frequency.value = opts.frequency ?? 700;
      const gain = ctx.createGain();
      const amp = opts.amplitude ?? 0.5;
      const dest = ctx.createMediaStreamDestination();
      osc.connect(gain).connect(dest);
      if (opts.spans && opts.loopSeconds) {
        gain.gain.value = 0;
        const t0 = ctx.currentTime + 0.1;
        // schedule ~60 s of looped keying
        for (let loop = 0; loop * opts.loopSeconds < 60; loop++) {
          for (const [s, e] of opts.spans) {
            const start = t0 + loop * opts.loopSeconds + s;
            const end = t0 + loop * opts.loopSeconds + e;
            gain.gain.setTargetAtTime(amp, start, 0.002);
            gain.gain.setTargetAtTime(0, end, 0.002);
          }
        }
      } else {
        gain.gain.value = amp;
      }
      osc.start();
      for (const track of dest.stream.getTracks()) {
        const stop = track.stop.bind(track);
        track.stop = () => {
          w.__fakeMic.stopped++;
          stop();
          void ctx.close();
        };
      }
      return dest.stream;
    };
  }, options);
}

export async function fakeMicStats(page: Page): Promise<{ calls: number; stopped: number }> {
  return page.evaluate(
    () => (window as unknown as { __fakeMic: { calls: number; stopped: number } }).__fakeMic,
  );
}
